    z_t82_t* boxed = (z_t82_t*)z_xmalloc(sizeof(z_t82_t));
    boxed->data = self->data;
    boxed->size = self->size - s->size;
    out.tag = Z_T10264_TAG_1;
    out.data = boxed;
